{"command":"python3 - << 'PY'
import subprocess, json
def run(args, inp):
    p=subprocess.run(["./executable"]+args, input=inp.encode(), capture_output=True)
    return p.stdout.decode(), p.stderr.decode(), p.returncode
def ev(**kw): return json.dumps(kw)+"\n"
def make(pkg,name,action,elapsed=0.1,lines=None):
    s=ev(Action="run",Package=pkg,Test=name)
    for o in (lines or []):
        s+=ev(Action="output",Package=pkg,Test=name,Output=o)
    s+=ev(Action=action,Package=pkg,Test=name,Elapsed=elapsed)
    return s
def pkgend(pkg,action,elapsed=0.2):
    return ev(Action="output",Package=pkg,Output="x\n")+ev(Action=action,Package=pkg,Elapsed=elapsed)

# ordering test
inp=""
for name,act,el in [("TestZebra","pass",0.01),("TestAlpha","pass",0.5),("TestMid","skip",0),("TestBeta","fail",0.02),("TestGamma","fail",0.03)]:
    inp+=make("p1",name,act,el,[f"output for {name}\n", f"--- {act.upper()}: {name}\n"])
inp+=pkgend("p1","fail",1.0)
for args in [["-nocolor","-all"],["-nocolor","-all","-sort","elapsed"],["-nocolor","-all","-sort","name"],["-nocolor","-all","-slow","2"],["-nocolor","-pass"],["-nocolor","-skip"]]:
    out,err,rc=run(args,inp)
    print("ARGS",args,rc)
    print(out)
    print("===")
PY"}

