from probe import *
def ispanic(line, scope="test"):
    if scope=="test":
        inp=ev(Action="output",Package="p",Test="T1",Output=line)+ev(Action="fail",Package="p",Test="T1",Elapsed=0.1)+ev(Action="fail",Package="p",Elapsed=0.2)
    else:
        inp=ev(Action="output",Package="p",Output=line)+ev(Action="fail",Package="p",Elapsed=0.2)
    rc,o,e=run(["-nocolor"],inp)
    return ("PANIC" in o, rc, o.splitlines()[0] if o else "")
