{"command":"cat > main.go <<'GOEOF'
package main

import (
	"bufio"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"

	"tparse/parse"
)

const usageText = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

var (
	optAll               bool
	optPass              bool
	optSkip              bool
	optNoTests           bool
	optSmallScreen       bool
	optSlow              int
	optSort              string
	optNoColor           bool
	optFormat            string
	optFile              string
	optFollow            bool
	optFollowOutput      string
	optIncludeTimestamp  bool
	optProgress          bool
	optCompare           string
	optTrimPath          string
	optHelp              bool
	optVersion           bool
	noColor              bool
	effectiveFormat      string
)

func main() {
	flag.BoolVar(&optHelp, "h", false, "")
	flag.BoolVar(&optHelp, "help", false, "")
	flag.BoolVar(&optVersion, "v", false, "")
	flag.BoolVar(&optVersion, "version", false, "")
	flag.Bool("all", false, "")
	// Use BoolVar for all flags below instead
	flag.BoolVar(&optAll, "all", false, "")
	flag.BoolVar(&optPass, "pass", false, "")
	flag.BoolVar(&optSkip, "skip", false, "")
	flag.BoolVar(&optNoTests, "notests", false, "")
	flag.BoolVar(&optSmallScreen, "smallscreen", false, "")
	flag.IntVar(&optSlow, "slow", 0, "")
	flag.StringVar(&optSort, "sort", "name", "")
	flag.BoolVar(&optNoColor, "nocolor", false, "")
	flag.StringVar(&optFormat, "format", "basic", "")
	flag.StringVar(&optFile, "file", "", "")
	flag.BoolVar(&optFollow, "follow", false, "")
	flag.StringVar(&optFollowOutput, "follow-output", "", "")
	flag.BoolVar(&optIncludeTimestamp, "include-timestamp", false, "")
	flag.BoolVar(&optProgress, "progress", false, "")
	flag.StringVar(&optCompare, "compare", "", "")
	flag.StringVar(&optTrimPath, "trimpath", "", "")
	flag.Usage = func() {
		fmt.Fprint(flag.CommandLine.Output(), usageText)
	}
	flag.Parse()

	if optVersion {
		fmt.Println("tparse version: (devel)")
		return
	}
	if optHelp {
		fmt.Fprint(os.Stdout, usageText)
		return
	}
	switch optFormat {
	case "basic", "plain", "markdown", "":
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", optFormat)
		return
	}
	switch optSort {
	case "name", "elapsed", "cover":
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", optSort)
		return
	}
	effectiveFormat = optFormat
	if effectiveFormat == "" {
		effectiveFormat = "basic"
	}
	if optNoColor {
		noColor = true
	}
	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		noColor = true
	}

	var followWriter io.Writer
	if optFollowOutput != "" {
		f, err := os.Create(optFollowOutput)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return
		}
		defer f.Close()
		followWriter = f
	} else if optFollow {
		followWriter = os.Stdout
	}

	var input io.Reader
	var inputFile *os.File
	if optFile != "" {
		f, err := os.Open(optFile)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		inputFile = f
		input = f
		defer f.Close()
	} else {
		fi, _ := os.Stdin.Stat()
		if fi == nil || (fi.Mode()&os.ModeNamedPipe) == 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(1)
		}
		input = os.Stdin
	}
	_ = inputFile

	res, err := parseInput(input, followWriter)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	render(os.Stdout, res)

	if optCompare != "" {
		cf, err := os.Open(optCompare)
		if err != nil {
			fmt.Fprintf(os.Stderr, "warning: failed to open against file: %s\n", optCompare)
		} else {
			_, perr := parseInput(cf, nil)
			cf.Close()
			if perr != nil {
				fmt.Fprintf(os.Stderr, "warning: failed to parse against file: %s\n", optCompare)
			}
		}
	}

	// Determine exit code.
	if len(res.builds) > 0 {
		os.Exit(2)
	}
	if len(res.panics) > 0 {
		os.Exit(1)
	}
	for _, p := range res.main {
		if p.Action == "fail" {
			os.Exit(1)
		}
	}
}

// ---------- data structures ----------

type testObj struct {
	Name     string
	Package  string
	Category string // "", "pass", "fail", "skip"
	Elapsed  float64
	Outputs  []string
}

func (t *testObj) status() string {
	switch t.Category {
	case "pass":
		return "PASS"
	case "skip":
		return "SKIP"
	default:
		return "FAIL"
	}
}

type pkgObj struct {
	Key        string
	Name       string
	Action     string
	FinalSet   bool
	Elapsed    float64
	Cached     bool
	CoverSet   bool
	Cover      float64
	Tests      []*testObj
	testByName map[string]*testObj

	NoTest       bool
	NoTestMsg    string
	NoTestPass   bool // box status should read PASS when no final
	BuildFailed  bool
	BuildMsg     string
}

func (p *pkgObj) getTest(name, pkg string) *testObj {
	if p.testByName == nil {
		p.testByName = make(map[string]*testObj)
	}
	if t, ok := p.testByName[name]; ok {
		return t
	}
	t := &testObj{Name: name, Package: pkg}
	p.testByName[name] = t
	p.Tests = append(p.Tests, t)
	return t
}

func (p *pkgObj) counts() (pass, fail, skip int) {
	for _, t := range p.Tests {
		switch t.status() {
		case "PASS":
			pass++
		case "SKIP":
			skip++
		default:
			fail++
		}
	}
	return
}

type buildObj struct {
	Key  string
	Name string
	Msg  string
}

type panicObj struct {
	Key      string
	Name     string
	Test     string
	Elapsed  float64
	Cached   bool
	CoverSet bool
	Cover    float64
	Stack    string
}

type result struct {
	main       map[string]*pkgObj
	builds     []*buildObj
	buildByKey map[string]*buildObj
	panics     []*panicObj
	panicByKey map[string]*panicObj
}

// ---------- parsing ----------

var buildRe = regexp.MustCompile(`^FAIL(.*)\[(build|setup) failed\]`)
var coverRe = regexp.MustCompile(`(\d{1,3}\.\d)%\s+of statements`)

func parseInput(r io.Reader, followWriter io.Writer) (*result, error) {
	res := &result{
		main:       make(map[string]*pkgObj),
		buildByKey: make(map[string]*buildObj),
		panicByKey: make(map[string]*panicObj),
	}
	getPkg := func(key string) *pkgObj {
		if p, ok := res.main[key]; ok {
			return p
		}
		p := &pkgObj{Key: key, testByName: make(map[string]*testObj)}
		res.main[key] = p
		return p
	}

	scanner := bufio.NewScanner(r)
	parsed := 0
	for scanner.Scan() {
		line := scanner.Text()
		var ev parse.Event
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			if parsed == 0 {
				if followWriter != nil {
					fmt.Fprintln(followWriter, line)
				}
				if m := buildRe.FindStringSubmatch(line); m != nil {
					name := strings.TrimSpace(m[1])
					msg := m[2] + " failed"
					if _, ok := res.buildByKey[name]; !ok {
						b := &buildObj{Key: name, Name: name, Msg: msg}
						res.buildByKey[name] = b
						res.builds = append(res.builds, b)
					}
				}
				continue
			}
			var synErr *json.SyntaxError
			if errors.As(err, &synErr) {
				return nil, errors.New("no parsable events: Make sure to run go test with -json flag")
			}
			return nil, err
		}
		parsed++

		// follow
		followWrote := false
		if followWriter != nil && ev.Output != "" && !isFollowNoise(ev.Test, ev.Output) {
			if optIncludeTimestamp {
				fmt.Fprintf(followWriter, "%s %s", ev.Time.Format(time.RFC3339), ev.Output)
			} else {
				fmt.Fprint(followWriter, ev.Output)
			}
			followWrote = true
		}

		// ImportPath build events
		if ev.ImportPath != "" {
			if followWriter != nil {
				if followWrote {
					fmt.Fprint(os.Stderr, ev.Output)
				}
			} else {
				fmt.Fprint(os.Stderr, ev.Output)
			}
			continue
		}

		// progress
		if optProgress && (ev.Action == "pass" || ev.Action == "fail") && ev.Test == "" && ev.Output == "" {
			fmt.Fprintf(os.Stdout, "[%s]\t%10s\t%s\n", displayStatus(strings.ToUpper(string(ev.Action))), fmt.Sprintf("%.2fs", ev.Elapsed), ev.Package)
		}

		// Panic mode for this package
		if po, ok := res.panicByKey[ev.Package]; ok {
			po.Stack += ev.Output
			continue
		}

		pkg := getPkg(ev.Package)

		if ev.Action == "start" {
			continue
		}

		// Classifiers based on Output
		if ev.Output != "" {
			if strings.HasPrefix(ev.Output, "panic: ") {
				po := &panicObj{
					Key:      ev.Package,
					Name:     ev.Package,
					Test:     ev.Test,
					Elapsed:  pkg.Elapsed,
					Cached:   pkg.Cached,
					CoverSet: pkg.CoverSet,
					Cover:    pkg.Cover,
					Stack:    ev.Output,
				}
				res.panicByKey[ev.Package] = po
				res.panics = append(res.panics, po)
				delete(res.main, ev.Package)
				continue
			}
			if strings.HasPrefix(ev.Output, "ok  \t") && strings.Contains(ev.Output, "\t(cached)") {
				pkg.Cached = true
			} else if strings.HasPrefix(ev.Output, "?   \t") && strings.HasSuffix(ev.Output, "[no test files]\n") {
				pkg.NoTest = true
				pkg.NoTestMsg = "no test files"
				pkg.NoTestPass = true
				pkg.Name = ev.Package
			} else if strings.HasPrefix(ev.Output, "ok  \t") && strings.HasSuffix(ev.Output, "[no tests to run]\n") {
				pkg.NoTest = true
				pkg.NoTestMsg = "no tests to run"
				pkg.NoTestPass = true
				pkg.Name = ev.Package
			} else if strings.Contains(ev.Output, "coverage:") {
				if m := coverRe.FindStringSubmatch(ev.Output); m != nil {
					if v, err := strconv.ParseFloat(m[1], 64); err == nil {
						pkg.CoverSet = true
						pkg.Cover = v
					}
				}
			}
		}

		// Dispatch
		if ev.Action == "output" {
			if ev.Test != "" {
				t := pkg.getTest(ev.Test, ev.Package)
				t.Outputs = append(t.Outputs, ev.Output)
				if ev.Elapsed > t.Elapsed {
					t.Elapsed = ev.Elapsed
				}
			}
		} else if (ev.Action == "pass" || ev.Action == "fail") && ev.Test == "" && ev.Output == "" {
			pkg.Name = ev.Package
			pkg.Action = string(ev.Action)
			pkg.Elapsed = ev.Elapsed
			pkg.FinalSet = true
		} else {
			t := pkg.getTest(ev.Test, ev.Package)
			if ev.Elapsed > t.Elapsed {
				t.Elapsed = ev.Elapsed
			}
			if ev.Action == "pass" || ev.Action == "fail" || ev.Action == "skip" {
				t.Category = string(ev.Action)
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("received scanning error: %w", err)
	}
	if parsed == 0 {
		return nil, errors.New("no parsable events: Make sure to run go test with -json flag")
	}
	total := len(res.main) + len(res.builds) + len(res.panics)
	if total == 0 {
		return nil, errors.New("found no go test packages")
	}
	return res, nil
}

func isFollowNoise(test, output string) bool {
	if test == "" {
		ts := strings.TrimSpace(output)
		if ts == "PASS" || ts == "FAIL" {
			return true
		}
	}
	for _, p := range []string{"=== RUN   ", "=== PAUSE ", "=== CONT  ", "--- PASS: ", "--- SKIP: "} {
		if strings.HasPrefix(output, p) {
			return true
		}
	}
	return false
}

func isTestNoise(output string) bool {
	for _, p := range []string{"=== RUN   ", "=== PAUSE ", "=== CONT  "} {
		if strings.HasPrefix(output, p) {
			return true
		}
	}
	return false
}

// ---------- display helpers ----------

func displayStatus(status string) string {
	if effectiveFormat == "markdown" {
		if noColor {
			return status
		}
		switch status {
		case "PASS":
			return "🟢 PASS"
		case "FAIL", "PANIC":
			return "🔴 " + status
		case "SKIP", "NOTEST":
			return "🟡 " + status
		default:
			return status
		}
	}
	if noColor {
		return status
	}
	switch status {
	case "PASS":
		return "\x1b[92m" + status + "\x1b[0m"
	case "FAIL", "PANIC":
		return "\x1b[91m" + status + "\x1b[0m"
	case "SKIP", "NOTEST":
		return "\x1b[93m" + status + "\x1b[0m"
	default:
		return status
	}
}

func displayPkgName(name string) string {
	if optTrimPath != "" {
		name = strings.TrimPrefix(name, optTrimPath)
	}
	if optSmallScreen {
		if idx := strings.LastIndex(name, "/"); idx >= 0 {
			name = name[idx+1:]
		}
	}
	return name
}

func formatTestName(name string) string {
	if !optSmallScreen {
		return name
	}
	if runeCount(name) <= 32 {
		return name
	}
	parts := strings.Split(name, "/")
	if len(parts) <= 1 {
		return name
	}
	var sb strings.Builder
	sb.WriteString(parts[0])
	for _, part := range parts[1:] {
		line := " /" + part
		sb.WriteString("\n")
		sb.WriteString(wrapTestLine(line))
	}
	return sb.String()
}

func runeCount(s string) int {
	return len([]rune(s))
}

// wrapTestLine wraps a line at 34 characters using hard 32+ellipsis wrapping.
func wrapTestLine(line string) string {
	var out []string
	cur := line
	for runeCount(cur) > 34 {
		runes := []rune(cur)
		first := string(runes[:32])
		out = append(out, first+" …")
		cur = "  " + string(runes[32:])
	}
	out = append(out, cur)
	return strings.Join(out, "\n")
}

// ---------- rendering / entries ----------

type entry struct {
	key      string
	name     string
	elapsed  float64
	cover    float64
	coverSet bool
	cached   bool
	main     *pkgObj
	build    *buildObj
	panic    *panicObj
}

func (e *entry) isPanic() bool { return e.panic != nil }
func (e *entry) isBuild() bool {
	if e.build != nil {
		return true
	}
	if e.main != nil && e.main.BuildFailed {
		return true
	}
	return false
}
func (e *entry) sortName() string { return e.name }

func buildEntries(res *result) []*entry {
	var entries []*entry
	// main packages in map iteration order
	for _, p := range res.main {
		entries = append(entries, &entry{key: p.Key, name: p.Name, elapsed: p.Elapsed, cover: p.Cover, coverSet: p.CoverSet, cached: p.Cached, main: p})
	}
	// build objects
	for _, b := range res.builds {
		// duplicate with main ? mark main as build failed, don't add separate entry
		found := false
		for _, e := range entries {
			if e.main != nil && e.key == b.Key {
				e.main.BuildFailed = true
				if e.main.FinalSet {
					e.main.BuildMsg = ""
				} else {
					e.main.BuildMsg = b.Msg
				}
				found = true
				break
			}
		}
		if !found {
			pm := &pkgObj{Key: b.Key, Name: b.Name, BuildFailed: true, BuildMsg: b.Msg, testByName: make(map[string]*testObj)}
			entries = append(entries, &entry{key: b.Key, name: b.Name, elapsed: 0, main: pm, build: b})
		}
	}
	for _, po := range res.panics {
		entries = append(entries, &entry{key: po.Key, name: po.Name, elapsed: po.Elapsed, cover: po.Cover, coverSet: po.CoverSet, cached: po.Cached, panic: po})
	}
	return entries
}

func sortEntries(entries []*entry) {
	sort.Slice(entries, func(i, j int) bool {
		switch optSort {
		case "elapsed":
			return entries[i].elapsed > entries[j].elapsed
		case "cover":
			return entries[i].cover > entries[j].cover
		default:
			return entries[i].name < entries[j].name
		}
	})
}

func cloneSorted(entries []*entry) []*entry {
	out := make([]*entry, len(entries))
	copy(out, entries)
	sortEntries(out)
	return out
}

func render(w io.Writer, res *result) {
	entries := buildEntries(res)
	sorted := cloneSorted(entries)

	showTests := optPass || optSkip || optAll
	showPass := optPass || optAll
	showSkip := optSkip || optAll

	// Test tables
	if showTests {
		if effectiveFormat == "markdown" {
			renderMarkdownTestSections(w, entries)
		} else {
			renderBasicTestTable(w, sorted, showPass, showSkip)
		}
	}

	// Failure / panic sections
	renderFailPanic(w, sorted)

	// Summary
	renderSummary(w, res, entries)
}

func qualifyingRowsForPackage(e *entry, showPass, showSkip bool) [][]string {
	if e.main == nil {
		return nil
	}
	p := e.main
	passTests := []*testObj{}
	skipTests := []*testObj{}
	failTests := []*testObj{}
	for _, t := range p.Tests {
		switch t.status() {
		case "PASS":
			passTests = append(passTests, t)
		case "SKIP":
			skipTests = append(skipTests, t)
		default:
			failTests = append(failTests, t)
		}
	}
	// Sort passes by elapsed descending
	sort.Slice(passTests, func(i, j int) bool {
		return passTests[i].Elapsed > passTests[j].Elapsed
	})
	if optSlow > 0 && len(passTests) > optSlow {
		passTests = passTests[:optSlow]
	}
	var rows [][]string
	mkRow := func(t *testObj) []string {
		return []string{displayStatus(t.status()), fmt.Sprintf("%.2f", t.Elapsed), formatTestName(t.Name), displayPkgName(t.Package)}
	}
	if showPass {
		for _, t := range passTests {
			rows = append(rows, mkRow(t))
		}
	}
	if showSkip {
		for _, t := range skipTests {
			rows = append(rows, mkRow(t))
		}
	}
	for _, t := range failTests {
		rows = append(rows, mkRow(t))
	}
	return rows
}

func renderBasicTestTable(w io.Writer, sorted []*entry, showPass, showSkip bool) {
	var rows [][]string
	for i, e := range sorted {
		if e.isPanic() {
			continue
		}
		if e.main != nil && e.main.NoTest {
			continue
		}
		rows = append(rows, qualifyingRowsForPackage(e, showPass, showSkip)...)
		if i < len(sorted)-1 {
			rows = append(rows, []string{"", "", "", ""})
		}
	}
	if len(rows) == 0 {
		return
	}
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	aligns := []int{alignCenter, alignCenter, alignLeft, alignLeft}
	fmt.Fprint(w, renderTable(headers, rows, aligns, effectiveFormat))
}

func renderMarkdownTestSections(w io.Writer, entries []*entry) {
	// Entries excluding panics and notest main packages, sorted
	var filtered []*entry
	for _, e := range entries {
		if e.isPanic() {
			continue
		}
		if e.main != nil && e.main.NoTest {
			continue
		}
		filtered = append(filtered, e)
	}
	sorted := cloneSorted(filtered)
	showPass := optPass || optAll
	showSkip := optSkip || optAll
	for _, e := range sorted {
		rowsWithPkg := qualifyingRowsForPackage(e, showPass, showSkip)
		if len(rowsWithPkg) == 0 {
			fmt.Fprintln(w, "")
			continue
		}
		// strip package column
		var rows [][]string
		for _, r := range rowsWithPkg {
			rows = append(rows, []string{r[0], r[1], r[2]})
		}
		passC, failC, skipC := 0, 0, 0
		if e.main != nil {
			passC, failC, skipC = e.main.counts()
		}
		pkgHeading := ""
		if e.main != nil {
			pkgHeading = e.main.Name
		} else if e.build != nil {
			pkgHeading = e.build.Name
		}
		headers := []string{"Status", "Elapsed", "Test"}
		aligns := []int{alignCenter, alignCenter, alignLeft}
		tableStr := renderTable(headers, rows, aligns, "markdown")
		section := fmt.Sprintf("## 📦 Package **`%s`**\n\nTests: ✓ %d passed | %d skipped | %d failed\n\n<details>\n\n<summary>Click for test summary</summary>\n\n%s</details>\n\n", pkgHeading, passC, skipC, failC, tableStr)
		fmt.Fprintln(w, section)
	}
}

// ---------- failures / panics ----------

func failedTests(p *pkgObj) []*testObj {
	var out []*testObj
	for _, t := range p.Tests {
		if t.status() == "FAIL" {
			out = append(out, t)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func boxStatusAndName(e *entry) (string, string) {
	if e.panic != nil {
		name := e.panic.Name
		if e.panic.Test != "" {
			// caller handles separately
			_ = name
		}
		return "PANIC", e.panic.Name
	}
	if e.main == nil {
		return "", ""
	}
	st := strings.ToUpper(e.main.Action)
	if st == "" && e.main.NoTest && e.main.NoTestPass {
		st = "PASS"
	}
	return st, e.main.Name
}

func renderFailPanic(w io.Writer, sorted []*entry) {
	for _, e := range sorted {
		if e.isPanic() {
			renderPanic(w, e)
			continue
		}
		if e.main == nil {
			continue
		}
		ft := failedTests(e.main)
		if len(ft) == 0 {
			continue
		}
		if effectiveFormat == "markdown" {
			st, pkgName := boxStatusAndName(e)
			headingStatus := st
			if !noColor {
				headingStatus = "🔴 " + st
			}
			fmt.Fprintf(w, "## %s • %s\n\n", headingStatus, pkgName)
			fmt.Fprint(w, "```\n")
			fmt.Fprint(w, failContent(e.main, true))
			fmt.Fprint(w, "```\n\n")
		} else {
			st, pkgName := boxStatusAndName(e)
			box := makeBox(st, pkgName, false)
			fmt.Fprint(w, box)
			fmt.Fprint(w, "\n")
			fmt.Fprint(w, failContent(e.main, false))
		}
	}
}

func makeBox(status, pkgName string, isPanic bool) string {
	// status display inside box
	var statusDisp string
	if noColor {
		statusDisp = status
	} else {
		statusDisp = "\x1b[91m\x1b[91m" + status + "\x1b[0m\x1b[0m"
	}
	var content string
	// For panic, caller composes content externally; this function is for fail boxes only.
	content = "   " + statusDisp + "  package: " + pkgName + "   "
	visibleContent := "   " + status + "  package: " + pkgName + "   "
	width := displayWidth(visibleContent)
	border := func(s string) string {
		if noColor {
			return s
		}
		return "\x1b[38;5;103m" + s + "\x1b[0m"
	}
	top := border("┏" + strings.Repeat("━", width) + "┓")
	mid := border("┃") + content + border("┃")
	bottom := border("┗" + strings.Repeat("━", width) + "┛")
	return top + "\n" + mid + "\n" + bottom + "\n"
}

func makePanicBox(po *panicObj) (string, string) {
	status := "PANIC"
	var statusDisp string
	if noColor {
		statusDisp = status
	} else {
		statusDisp = "\x1b[91m\x1b[91m" + status + "\x1b[0m\x1b[0m"
	}
	var visible string
	var content string
	if po.Test != "" {
		visible = "   " + status + "  package: " + po.Name + " • " + po.Test + "   "
		content = "   " + statusDisp + "  package: " + po.Name + " • " + po.Test + "   "
	} else {
		visible = "   " + status + "  package: " + po.Name + "   "
		content = "   " + statusDisp + "  package: " + po.Name + "   "
	}
	width := displayWidth(visible)
	border := func(s string) string {
		if noColor {
			return s
		}
		return "\x1b[38;5;103m" + s + "\x1b[0m"
	}
	top := border("┏" + strings.Repeat("━", width) + "┓")
	mid := border("┃") + content + border("┃")
	bottom := border("┗" + strings.Repeat("━", width) + "┛")
	return top + "\n" + mid + "\n" + bottom + "\n", visible
}

func renderPanic(w io.Writer, e *entry) {
	po := e.panic
	if effectiveFormat == "markdown" {
		statusDisp := "PANIC"
		if !noColor {
			statusDisp = "🔴 PANIC"
		}
		heading := "## " + statusDisp + " • " + po.Name
		if po.Test != "" {
			heading += " • " + po.Test
		}
		width := 96
		if dw := displayWidth(heading); dw > width {
			width = dw
		}
		// heading padded
		fmt.Fprint(w, padRight(heading, width)+"\n")
		renderPanicStack(w, po.Stack, width)
	} else {
		box, _ := makePanicBox(po)
		// box lines are already newline terminated; determine width from box visible width
		// visible width = display width of first box line without ANSI
		firstLine := strings.Split(box, "\n")[0]
		width := 96
		if dw := displayWidth(firstLine); dw > width {
			width = dw
		}
		// print box padded
		lines := strings.Split(strings.TrimSuffix(box, "\n"), "\n")
		for _, l := range lines {
			fmt.Fprint(w, padRight(l, width)+"\n")
		}
		renderPanicStack(w, po.Stack, width)
	}
}

func renderPanicStack(w io.Writer, stack string, width int) {
	text := strings.ReplaceAll(stack, "\t", "    ")
	// split into logical lines; strings.Split preserves trailing empty segment
	logical := strings.Split(text, "\n")
	for _, line := range logical {
		wrapped := wrapLineWord(line, width)
		for _, wl := range wrapped {
			fmt.Fprint(w, padRight(wl, width)+"\n")
		}
	}
}

// padRight pads a string (possibly with ANSI) to display width.
func padRight(s string, width int) string {
	dw := displayWidth(s)
	if dw >= width {
		return s
	}
	return s + strings.Repeat(" ", width-dw)
}

// wrapLineWord wraps a single logical line to width using greedy word wrapping,
// breaking long words.
func wrapLineWord(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	if displayWidth(line) <= width {
		return []string{line}
	}
	// Tokenize preserving spaces
	type token struct {
		text  string
		isSpace bool
	}
	var toks []token
	i := 0
	runes := []rune(line)
	for i < len(runes) {
		if runes[i] == ' ' {
			j := i
			for j < len(runes) && runes[j] == ' ' {
				j++
			}
			toks = append(toks, token{string(runes[i:j]), true})
			i = j
		} else {
			j := i
			for j < len(runes) && runes[j] != ' ' {
				j++
			}
			toks = append(toks, token{string(runes[i:j]), false})
			i = j
		}
	}
	var lines []string
	cur := ""
	flush := func() {
		lines = append(lines, cur)
		cur = ""
	}
	for _, tok := range toks {
		if tok.isSpace {
			cur += tok.text
			continue
		}
		// word
		if displayWidth(cur)+displayWidth(tok.text) <= width {
			cur += tok.text
			continue
		}
		// word doesn't fit
		if displayWidth(tok.text) > width {
			// emit current line if any content (even just spaces)
			if cur != "" {
				flush()
			}
			// break word into width sized chunks
			wr := []rune(tok.text)
			// Use display width aware chunking; simple rune slice when ascii
			for displayWidth(string(wr)) > width {
				// take prefix with display width <= width
				end := 0
				wsum := 0
				for end < len(wr) {
					rw := runeDisplayWidth(wr[end])
					if wsum+rw > width {
						break
					}
					wsum += rw
					end++
				}
				if end == 0 {
					end = 1
				}
				lines = append(lines, string(wr[:end]))
				wr = wr[end:]
			}
			cur = string(wr)
			continue
		}
		// fits on its own line
		flush()
		cur = tok.text
	}
	// last line
	lines = append(lines, cur)
	return lines
}

func failContent(p *pkgObj, markdown bool) string {
	ft := failedTests(p)
	var sb strings.Builder
	for i, t := range ft {
		if i > 0 && !strings.Contains(t.Name, "/") {
			sb.WriteString(strings.Repeat("─", 96) + "\n")
			if !markdown && !noColor {
				sb.WriteString("\x1b[2m\x1b[0m")
			}
			sb.WriteString(strings.Repeat(" ", 96) + "\n")
		}
		headers, body := parseTestOutputs(t)
		var headerDisp strings.Builder
		for _, h := range headers {
			if !markdown && !noColor {
				headerDisp.WriteString("\x1b[31m" + h + "\x1b[0m")
			} else {
				headerDisp.WriteString(h)
			}
		}
		sb.WriteString(headerDisp.String() + "\n")
		if body != "" {
			sb.WriteString("\n")
			sb.WriteString(body)
			sb.WriteString("\n")
		}
	}
	return sb.String()
}

func parseTestOutputs(t *testObj) (headers []string, body string) {
	var bodySb strings.Builder
	for _, out := range t.Outputs {
		if idx := strings.Index(out, "--- FAIL: "); idx >= 0 {
			prefix := out[:idx]
			spaces := strings.Count(prefix, " ")
			indent := strings.Repeat(" ", spaces/2)
			seg := out[idx:]
			seg = strings.TrimSuffix(seg, "\n")
			seg = strings.ReplaceAll(seg, "\t", "    ")
			headers = append(headers, indent+seg)
		} else if isTestNoise(out) {
			continue
		} else {
			bodySb.WriteString(out)
		}
	}
	return headers, bodySb.String()
}

// ---------- summary ----------

func renderSummary(w io.Writer, res *result, entries []*entry) {
	// Determine groups
	sorted := cloneSorted(entries)

	var special, regular, notest []*entry
	for _, e := range sorted {
		if e.isPanic() || e.isBuild() {
			// dedupe panic vs build by key: if panic and build both, panic wins later; handle below
			special = append(special, e)
			continue
		}
		if e.main != nil && e.main.NoTest {
			notest = append(notest, e)
			continue
		}
		// cov suppression
		if e.main != nil && len(e.main.Tests) == 0 && e.main.CoverSet && e.main.Cover == 0 {
			continue
		}
		regular = append(regular, e)
	}
	// Dedupe special by key preferring panic
	{
		byKey := make(map[string]*entry)
		var keys []string
		for _, e := range special {
			if existing, ok := byKey[e.key]; ok {
				if existing.isPanic() {
					continue
				}
				if e.isPanic() {
					byKey[e.key] = e
				}
				continue
			}
			byKey[e.key] = e
			keys = append(keys, e.key)
		}
		// rebuild special preserving sorted order but only keep chosen entries
		var deduped []*entry
		seen := make(map[string]bool)
		for _, e := range special {
			chosen := byKey[e.key]
			if chosen == e && !seen[e.key] {
				deduped = append(deduped, e)
				seen[e.key] = true
			}
		}
		special = deduped
		// Remove regular/notest entries whose key is in special
		// (regular already excludes build, panic not in main; but BF duplicate main is in special as main entry, fine)
		_ = keys
	}
	// If a package is in special, it shouldn't also be in notest (already handled: build before notest, panic not main)
	// Inclusion of notest
	showNotest := optNoTests
	if !showNotest {
		if len(res.main) == 1 {
			showNotest = true
		}
	}

	var rows [][]string
	addRow := func(e *entry) {
		st := summaryStatus(e)
		elapsed := ""
		if e.cached {
			elapsed = "(cached)"
		} else {
			elapsed = fmt.Sprintf("%.2fs", e.elapsed)
		}
		cover := "--"
		counts := []string{"--", "--", "--"}
		isSpecialCat := e.isPanic() || e.isBuild() || (e.main != nil && e.main.NoTest)
		if !isSpecialCat && e.coverSet {
			cover = fmt.Sprintf("%.1f%%", e.cover)
		}
		if !isSpecialCat && e.main != nil {
			pc, fc, sc := e.main.counts()
			counts = []string{strconv.Itoa(pc), strconv.Itoa(fc), strconv.Itoa(sc)}
		}
		pkgDisp := ""
		if e.isPanic() {
			pkgDisp = displayPkgName(e.panic.Name)
		} else if e.main != nil {
			base := displayPkgName(e.main.Name)
			if e.isBuild() {
				pkgDisp = base + "\n[" + e.main.BuildMsg + "]"
			} else if e.main.NoTest {
				pkgDisp = base + "\n[" + e.main.NoTestMsg + "]"
			} else {
				pkgDisp = base
			}
		}
		rows = append(rows, []string{displayStatus(st), elapsed, pkgDisp, cover, counts[0], counts[1], counts[2]})
	}
	for _, e := range special {
		addRow(e)
	}
	for _, e := range regular {
		addRow(e)
	}
	if showNotest {
		for _, e := range notest {
			addRow(e)
		}
	}

	if len(rows) == 0 && len(notest) == 0 {
		return
	}
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	aligns := []int{alignCenter, alignCenter, alignLeft, alignCenter, alignCenter, alignCenter, alignCenter}
	fmt.Fprint(w, renderTable(headers, rows, aligns, effectiveFormat))
}

func summaryStatus(e *entry) string {
	if e.isPanic() {
		return "PANIC"
	}
	if e.isBuild() {
		return "FAIL"
	}
	if e.main != nil && e.main.NoTest {
		return "NOTEST"
	}
	if e.main != nil {
		switch e.main.Action {
		case "pass":
			return "PASS"
		case "fail":
			return "FAIL"
		}
	}
	return ""
}

// ---------- table rendering ----------

const (
	alignCenter = iota
	alignLeft
)

func renderTable(headers []string, rows [][]string, aligns []int, style string) string {
	ncols := len(headers)
	// compute widths
	widths := make([]int, ncols)
	for i, h := range headers {
		widths[i] = displayWidth(h)
	}
	// normalize rows and split cells
	type splitRow [][]string
	var splitRows []splitRow
	for _, r := range rows {
		var sr splitRow
		for i := 0; i < ncols; i++ {
			cell := ""
			if i < len(r) {
				cell = r[i]
			}
			// tab expansion to 4 spaces for display (go-pretty like)
			// only if cell does not contain ANSI? keep simple: replace tabs
			// Split into lines
			lines := strings.Split(cell, "\n")
			sr = append(sr, lines)
			for _, ln := range lines {
				if dw := displayWidth(ln); dw > widths[i] {
					widths[i] = dw
				}
			}
		}
		splitRows = append(splitRows, sr)
	}

	var sb strings.Builder
	formatLine := func(cells []string, isHeader bool) string {
		var parts []string
		for i := 0; i < ncols; i++ {
			txt := ""
			if i < len(cells) {
				txt = cells[i]
			}
			aligned := alignText(txt, widths[i], alignCenter) // headers always center
			if !isHeader {
				if aligns[i] == alignLeft {
					aligned = alignText(txt, widths[i], alignLeft)
				} else {
					aligned = alignText(txt, widths[i], alignCenter)
				}
			}
			parts = append(parts, " "+aligned+" ")
		}
		switch style {
		case "markdown":
			return "|" + strings.Join(parts, "|") + "|\n"
		case "plain":
			// replace border with space: build like basic but with spaces
			return " " + strings.Join(parts, " ") + " \n"
		default: // basic
			return "│" + strings.Join(parts, "│") + "│\n"
		}
	}

	if style == "markdown" {
		sb.WriteString(formatLine(headers, true))
		// separator
		var seps []string
		for i := 0; i < ncols; i++ {
			seps = append(seps, strings.Repeat("-", widths[i]+2))
		}
		sb.WriteString("|" + strings.Join(seps, "|") + "|\n")
	} else if style == "plain" {
		sb.WriteString(formatLine(headers, true))
		// blank separator line: total width
		total := 0
		// compute total from a formatted line display width
		hl := formatLine(headers, true)
		total = displayWidth(strings.TrimSuffix(hl, "\n"))
		sb.WriteString(strings.Repeat(" ", total) + "\n")
	} else {
		// basic top
		sb.WriteString(borderLine(widths, "╭", "┬", "╮"))
		sb.WriteString(formatLine(headers, true))
		sb.WriteString(borderLine(widths, "├", "┼", "┤"))
	}
	// rows
	for _, sr := range splitRows {
		maxLines := 1
		for _, cellLines := range sr {
			if len(cellLines) > maxLines {
				maxLines = len(cellLines)
			}
		}
		for li := 0; li < maxLines; li++ {
			var cells []string
			for i := 0; i < ncols; i++ {
				if li < len(sr[i]) {
					cells = append(cells, sr[i][li])
				} else {
					cells = append(cells, "")
				}
			}
			sb.WriteString(formatLine(cells, false))
		}
	}
	if style != "markdown" && style != "plain" {
		sb.WriteString(borderLine(widths, "╰", "┴", "╯"))
	}
	return sb.String()
}

func borderLine(widths []int, left, mid, right string) string {
	var parts []string
	for _, w := range widths {
		parts = append(parts, strings.Repeat("─", w+2))
	}
	return left + strings.Join(parts, mid) + right + "\n"
}

func alignText(s string, width int, align int) string {
	dw := displayWidth(s)
	if dw >= width {
		return s
	}
	pad := width - dw
	if align == alignLeft {
		return s + strings.Repeat(" ", pad)
	}
	left := pad / 2
	right := pad - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

// displayWidth computes visible width stripping ANSI sequences.
var ansiRe = regexp.MustCompile("\x1b\\[[0-9;]*[A-Za-z]")

func displayWidth(s string) int {
	stripped := ansiRe.ReplaceAllString(s, "")
	w := 0
	for _, r := range stripped {
		w += runeDisplayWidth(r)
	}
	return w
}

func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 32 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Cf, r) {
		return 0
	}
	// Wide / fullwidth ranges approximating go-runewidth
	if isWideRune(r) {
		return 2
	}
	return 1
}

func isWideRune(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, // Hangul Jamo
		r >= 0x2329 && r <= 0x232A,
		r >= 0x2E80 && r <= 0x303E,
		r >= 0x3041 && r <= 0x33FF,
		r >= 0x3400 && r <= 0x4DBF,
		r >= 0x4E00 && r <= 0x9FFF,
		r >= 0xA000 && r <= 0xA4C6,
		r >= 0xAC00 && r <= 0xD7A3,
		r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE10 && r <= 0xFE19,
		r >= 0xFE30 && r <= 0xFE52,
		r >= 0xFE54 && r <= 0xFE66,
		r >= 0xFE68 && r <= 0xFE6B,
		r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6,
		r >= 0x16FE0 && r <= 0x16FE4,
		r >= 0x17000 && r <= 0x187F7,
		r >= 0x18800 && r <= 0x18CD5,
		r >= 0x1B000 && r <= 0x1B2FB,
		r >= 0x1F004 && r <= 0x1F004,
		r >= 0x1F0CF && r <= 0x1F0CF,
		r >= 0x1F18E && r <= 0x1F18E,
		r >= 0x1F191 && r <= 0x1F19A,
		r >= 0x1F200 && r <= 0x1F320,
		r >= 0x1F32D && r <= 0x1F335,
		r >= 0x1F337 && r <= 0x1F37C,
		r >= 0x1F37E && r <= 0x1F393,
		r >= 0x1F3A0 && r <= 0x1F3CA,
		r >= 0x1F3CF && r <= 0x1F3D3,
		r >= 0x1F3E0 && r <= 0x1F3F0,
		r >= 0x1F3F4 && r <= 0x1F3F4,
		r >= 0x1F3F8 && r <= 0x1F43E,
		r >= 0x1F440 && r <= 0x1F440,
		r >= 0x1F442 && r <= 0x1F4FC,
		r >= 0x1F4FF && r <= 0x1F53D,
		r >= 0x1F54B && r <= 0x1F54E,
		r >= 0x1F550 && r <= 0x1F567,
		r >= 0x1F57A && r <= 0x1F57A,
		r >= 0x1F595 && r <= 0x1F596,
		r >= 0x1F5A4 && r <= 0x1F5A4,
		r >= 0x1F5FB && r <= 0x1F64F,
		r >= 0x1F680 && r <= 0x1F6C5,
		r >= 0x1F6CC && r <= 0x1F6CC,
		r >= 0x1F6D0 && r <= 0x1F6D2,
		r >= 0x1F6D5 && r <= 0x1F6D7,
		r >= 0x1F6DC && r <= 0x1F6DF,
		r >= 0x1F6EB && r <= 0x1F6EC,
		r >= 0x1F6F4 && r <= 0x1F6FC,
		r >= 0x1F7E0 && r <= 0x1F7EB,
		r >= 0x1F7F0 && r <= 0x1F7F0,
		r >= 0x1F90C && r <= 0x1F93A,
		r >= 0x1F93C && r <= 0x1F945,
		r >= 0x1F947 && r <= 0x1F9CB,
		r >= 0x1F9CD && r <= 0x1F9FF,
		r >= 0x1FA70 && r <= 0x1FA74,
		r >= 0x1FA78 && r <= 0x1FA7C,
		r >= 0x1FA80 && r <= 0x1FA86,
		r >= 0x1FA90 && r <= 0x1FAAC,
		r >= 0x1FAB0 && r <= 0x1FABA,
		r >= 0x1FAC0 && r <= 0x1FAC5,
		r >= 0x1FAD0 && r <= 0x1FAD9,
		r >= 0x1FAE0 && r <= 0x1FAE7,
		r >= 0x1FAF0 && r <= 0x1FAF6,
		r >= 0x20000 && r <= 0x2FFFD,
		r >= 0x30000 && r <= 0x3FFFD:
		return true
	}
	return false
}
GOEOF
"}

actions.command:
cat > main.go <<'GOEOF'
package main

import (
	"bufio"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"

	"tparse/parse"
)

const usageText = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

var (
	optAll               bool
	optPass              bool
	optSkip              bool
	optNoTests           bool
	optSmallScreen       bool
	optSlow              int
	optSort              string
	optNoColor           bool
	optFormat            string
	optFile              string
	optFollow            bool
	optFollowOutput      string
	optIncludeTimestamp  bool
	optProgress          bool
	optCompare           string
	optTrimPath          string
	optHelp              bool
	optVersion           bool
	noColor              bool
	effectiveFormat      string
)

func main() {
	flag.BoolVar(&optHelp, "h", false, "")
	flag.BoolVar(&optHelp, "help", false, "")
	flag.BoolVar(&optVersion, "v", false, "")
	flag.BoolVar(&optVersion, "version", false, "")
	flag.Bool("all", false, "")
	// Use BoolVar for all flags below instead
	flag.BoolVar(&optAll, "all", false, "")
	flag.BoolVar(&optPass, "pass", false, "")
	flag.BoolVar(&optSkip, "skip", false, "")
	flag.BoolVar(&optNoTests, "notests", false, "")
	flag.BoolVar(&optSmallScreen, "smallscreen", false, "")
	flag.IntVar(&optSlow, "slow", 0, "")
	flag.StringVar(&optSort, "sort", "name", "")
	flag.BoolVar(&optNoColor, "nocolor", false, "")
	flag.StringVar(&optFormat, "format", "basic", "")
	flag.StringVar(&optFile, "file", "", "")
	flag.BoolVar(&optFollow, "follow", false, "")
	flag.StringVar(&optFollowOutput, "follow-output", "", "")
	flag.BoolVar(&optIncludeTimestamp, "include-timestamp", false, "")
	flag.BoolVar(&optProgress, "progress", false, "")
	flag.StringVar(&optCompare, "compare", "", "")
	flag.StringVar(&optTrimPath, "trimpath", "", "")
	flag.Usage = func() {
		fmt.Fprint(flag.CommandLine.Output(), usageText)
	}
	flag.Parse()

	if optVersion {
		fmt.Println("tparse version: (devel)")
		return
	}
	if optHelp {
		fmt.Fprint(os.Stdout, usageText)
		return
	}
	switch optFormat {
	case "basic", "plain", "markdown", "":
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", optFormat)
		return
	}
	switch optSort {
	case "name", "elapsed", "cover":
	default:
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", optSort)
		return
	}
	effectiveFormat = optFormat
	if effectiveFormat == "" {
		effectiveFormat = "basic"
	}
	if optNoColor {
		noColor = true
	}
	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		noColor = true
	}

	var followWriter io.Writer
	if optFollowOutput != "" {
		f, err := os.Create(optFollowOutput)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return
		}
		defer f.Close()
		followWriter = f
	} else if optFollow {
		followWriter = os.Stdout
	}

	var input io.Reader
	var inputFile *os.File
	if optFile != "" {
		f, err := os.Open(optFile)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		inputFile = f
		input = f
		defer f.Close()
	} else {
		fi, _ := os.Stdin.Stat()
		if fi == nil || (fi.Mode()&os.ModeNamedPipe) == 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(1)
		}
		input = os.Stdin
	}
	_ = inputFile

	res, err := parseInput(input, followWriter)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	render(os.Stdout, res)

	if optCompare != "" {
		cf, err := os.Open(optCompare)
		if err != nil {
			fmt.Fprintf(os.Stderr, "warning: failed to open against file: %s\n", optCompare)
		} else {
			_, perr := parseInput(cf, nil)
			cf.Close()
			if perr != nil {
				fmt.Fprintf(os.Stderr, "warning: failed to parse against file: %s\n", optCompare)
			}
		}
	}

	// Determine exit code.
	if len(res.builds) > 0 {
		os.Exit(2)
	}
	if len(res.panics) > 0 {
		os.Exit(1)
	}
	for _, p := range res.main {
		if p.Action == "fail" {
			os.Exit(1)
		}
	}
}

// ---------- data structures ----------

type testObj struct {
	Name     string
	Package  string
	Category string // "", "pass", "fail", "skip"
	Elapsed  float64
	Outputs  []string
}

func (t *testObj) status() string {
	switch t.Category {
	case "pass":
		return "PASS"
	case "skip":
		return "SKIP"
	default:
		return "FAIL"
	}
}

type pkgObj struct {
	Key        string
	Name       string
	Action     string
	FinalSet   bool
	Elapsed    float64
	Cached     bool
	CoverSet   bool
	Cover      float64
	Tests      []*testObj
	testByName map[string]*testObj

	NoTest       bool
	NoTestMsg    string
	NoTestPass   bool // box status should read PASS when no final
	BuildFailed  bool
	BuildMsg     string
}

func (p *pkgObj) getTest(name, pkg string) *testObj {
	if p.testByName == nil {
		p.testByName = make(map[string]*testObj)
	}
	if t, ok := p.testByName[name]; ok {
		return t
	}
	t := &testObj{Name: name, Package: pkg}
	p.testByName[name] = t
	p.Tests = append(p.Tests, t)
	return t
}

func (p *pkgObj) counts() (pass, fail, skip int) {
	for _, t := range p.Tests {
		switch t.status() {
		case "PASS":
			pass++
		case "SKIP":
			skip++
		default:
			fail++
		}
	}
	return
}

type buildObj struct {
	Key  string
	Name string
	Msg  string
}

type panicObj struct {
	Key      string
	Name     string
	Test     string
	Elapsed  float64
	Cached   bool
	CoverSet bool
	Cover    float64
	Stack    string
}

type result struct {
	main       map[string]*pkgObj
	builds     []*buildObj
	buildByKey map[string]*buildObj
	panics     []*panicObj
	panicByKey map[string]*panicObj
}

// ---------- parsing ----------

var buildRe = regexp.MustCompile(`^FAIL(.*)\[(build|setup) failed\]`)
var coverRe = regexp.MustCompile(`(\d{1,3}\.\d)%\s+of statements`)

func parseInput(r io.Reader, followWriter io.Writer) (*result, error) {
	res := &result{
		main:       make(map[string]*pkgObj),
		buildByKey: make(map[string]*buildObj),
		panicByKey: make(map[string]*panicObj),
	}
	getPkg := func(key string) *pkgObj {
		if p, ok := res.main[key]; ok {
			return p
		}
		p := &pkgObj{Key: key, testByName: make(map[string]*testObj)}
		res.main[key] = p
		return p
	}

	scanner := bufio.NewScanner(r)
	parsed := 0
	for scanner.Scan() {
		line := scanner.Text()
		var ev parse.Event
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			if parsed == 0 {
				if followWriter != nil {
					fmt.Fprintln(followWriter, line)
				}
				if m := buildRe.FindStringSubmatch(line); m != nil {
					name := strings.TrimSpace(m[1])
					msg := m[2] + " failed"
					if _, ok := res.buildByKey[name]; !ok {
						b := &buildObj{Key: name, Name: name, Msg: msg}
						res.buildByKey[name] = b
						res.builds = append(res.builds, b)
					}
				}
				continue
			}
			var synErr *json.SyntaxError
			if errors.As(err, &synErr) {
				return nil, errors.New("no parsable events: Make sure to run go test with -json flag")
			}
			return nil, err
		}
		parsed++

		// follow
		followWrote := false
		if followWriter != nil && ev.Output != "" && !isFollowNoise(ev.Test, ev.Output) {
			if optIncludeTimestamp {
				fmt.Fprintf(followWriter, "%s %s", ev.Time.Format(time.RFC3339), ev.Output)
			} else {
				fmt.Fprint(followWriter, ev.Output)
			}
			followWrote = true
		}

		// ImportPath build events
		if ev.ImportPath != "" {
			if followWriter != nil {
				if followWrote {
					fmt.Fprint(os.Stderr, ev.Output)
				}
			} else {
				fmt.Fprint(os.Stderr, ev.Output)
			}
			continue
		}

		// progress
		if optProgress && (ev.Action == "pass" || ev.Action == "fail") && ev.Test == "" && ev.Output == "" {
			fmt.Fprintf(os.Stdout, "[%s]\t%10s\t%s\n", displayStatus(strings.ToUpper(string(ev.Action))), fmt.Sprintf("%.2fs", ev.Elapsed), ev.Package)
		}

		// Panic mode for this package
		if po, ok := res.panicByKey[ev.Package]; ok {
			po.Stack += ev.Output
			continue
		}

		pkg := getPkg(ev.Package)

		if ev.Action == "start" {
			continue
		}

		// Classifiers based on Output
		if ev.Output != "" {
			if strings.HasPrefix(ev.Output, "panic: ") {
				po := &panicObj{
					Key:      ev.Package,
					Name:     ev.Package,
					Test:     ev.Test,
					Elapsed:  pkg.Elapsed,
					Cached:   pkg.Cached,
					CoverSet: pkg.CoverSet,
					Cover:    pkg.Cover,
					Stack:    ev.Output,
				}
				res.panicByKey[ev.Package] = po
				res.panics = append(res.panics, po)
				delete(res.main, ev.Package)
				continue
			}
			if strings.HasPrefix(ev.Output, "ok  \t") && strings.Contains(ev.Output, "\t(cached)") {
				pkg.Cached = true
			} else if strings.HasPrefix(ev.Output, "?   \t") && strings.HasSuffix(ev.Output, "[no test files]\n") {
				pkg.NoTest = true
				pkg.NoTestMsg = "no test files"
				pkg.NoTestPass = true
				pkg.Name = ev.Package
			} else if strings.HasPrefix(ev.Output, "ok  \t") && strings.HasSuffix(ev.Output, "[no tests to run]\n") {
				pkg.NoTest = true
				pkg.NoTestMsg = "no tests to run"
				pkg.NoTestPass = true
				pkg.Name = ev.Package
			} else if strings.Contains(ev.Output, "coverage:") {
				if m := coverRe.FindStringSubmatch(ev.Output); m != nil {
					if v, err := strconv.ParseFloat(m[1], 64); err == nil {
						pkg.CoverSet = true
						pkg.Cover = v
					}
				}
			}
		}

		// Dispatch
		if ev.Action == "output" {
			if ev.Test != "" {
				t := pkg.getTest(ev.Test, ev.Package)
				t.Outputs = append(t.Outputs, ev.Output)
				if ev.Elapsed > t.Elapsed {
					t.Elapsed = ev.Elapsed
				}
			}
		} else if (ev.Action == "pass" || ev.Action == "fail") && ev.Test == "" && ev.Output == "" {
			pkg.Name = ev.Package
			pkg.Action = string(ev.Action)
			pkg.Elapsed = ev.Elapsed
			pkg.FinalSet = true
		} else {
			t := pkg.getTest(ev.Test, ev.Package)
			if ev.Elapsed > t.Elapsed {
				t.Elapsed = ev.Elapsed
			}
			if ev.Action == "pass" || ev.Action == "fail" || ev.Action == "skip" {
				t.Category = string(ev.Action)
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("received scanning error: %w", err)
	}
	if parsed == 0 {
		return nil, errors.New("no parsable events: Make sure to run go test with -json flag")
	}
	total := len(res.main) + len(res.builds) + len(res.panics)
	if total == 0 {
		return nil, errors.New("found no go test packages")
	}
	return res, nil
}

func isFollowNoise(test, output string) bool {
	if test == "" {
		ts := strings.TrimSpace(output)
		if ts == "PASS" || ts == "FAIL" {
			return true
		}
	}
	for _, p := range []string{"=== RUN   ", "=== PAUSE ", "=== CONT  ", "--- PASS: ", "--- SKIP: "} {
		if strings.HasPrefix(output, p) {
			return true
		}
	}
	return false
}

func isTestNoise(output string) bool {
	for _, p := range []string{"=== RUN   ", "=== PAUSE ", "=== CONT  "} {
		if strings.HasPrefix(output, p) {
			return true
		}
	}
	return false
}

// ---------- display helpers ----------

func displayStatus(status string) string {
	if effectiveFormat == "markdown" {
		if noColor {
			return status
		}
		switch status {
		case "PASS":
			return "🟢 PASS"
		case "FAIL", "PANIC":
			return "🔴 " + status
		case "SKIP", "NOTEST":
			return "🟡 " + status
		default:
			return status
		}
	}
	if noColor {
		return status
	}
	switch status {
	case "PASS":
		return "\x1b[92m" + status + "\x1b[0m"
	case "FAIL", "PANIC":
		return "\x1b[91m" + status + "\x1b[0m"
	case "SKIP", "NOTEST":
		return "\x1b[93m" + status + "\x1b[0m"
	default:
		return status
	}
}

func displayPkgName(name string) string {
	if optTrimPath != "" {
		name = strings.TrimPrefix(name, optTrimPath)
	}
	if optSmallScreen {
		if idx := strings.LastIndex(name, "/"); idx >= 0 {
			name = name[idx+1:]
		}
	}
	return name
}

func formatTestName(name string) string {
	if !optSmallScreen {
		return name
	}
	if runeCount(name) <= 32 {
		return name
	}
	parts := strings.Split(name, "/")
	if len(parts) <= 1 {
		return name
	}
	var sb strings.Builder
	sb.WriteString(parts[0])
	for _, part := range parts[1:] {
		line := " /" + part
		sb.WriteString("\n")
		sb.WriteString(wrapTestLine(line))
	}
	return sb.String()
}

func runeCount(s string) int {
	return len([]rune(s))
}

// wrapTestLine wraps a line at 34 characters using hard 32+ellipsis wrapping.
func wrapTestLine(line string) string {
	var out []string
	cur := line
	for runeCount(cur) > 34 {
		runes := []rune(cur)
		first := string(runes[:32])
		out = append(out, first+" …")
		cur = "  " + string(runes[32:])
	}
	out = append(out, cur)
	return strings.Join(out, "\n")
}

// ---------- rendering / entries ----------

type entry struct {
	key      string
	name     string
	elapsed  float64
	cover    float64
	coverSet bool
	cached   bool
	main     *pkgObj
	build    *buildObj
	panic    *panicObj
}

func (e *entry) isPanic() bool { return e.panic != nil }
func (e *entry) isBuild() bool {
	if e.build != nil {
		return true
	}
	if e.main != nil && e.main.BuildFailed {
		return true
	}
	return false
}
func (e *entry) sortName() string { return e.name }

func buildEntries(res *result) []*entry {
	var entries []*entry
	// main packages in map iteration order
	for _, p := range res.main {
		entries = append(entries, &entry{key: p.Key, name: p.Name, elapsed: p.Elapsed, cover: p.Cover, coverSet: p.CoverSet, cached: p.Cached, main: p})
	}
	// build objects
	for _, b := range res.builds {
		// duplicate with main ? mark main as build failed, don't add separate entry
		found := false
		for _, e := range entries {
			if e.main != nil && e.key == b.Key {
				e.main.BuildFailed = true
				if e.main.FinalSet {
					e.main.BuildMsg = ""
				} else {
					e.main.BuildMsg = b.Msg
				}
				found = true
				break
			}
		}
		if !found {
			pm := &pkgObj{Key: b.Key, Name: b.Name, BuildFailed: true, BuildMsg: b.Msg, testByName: make(map[string]*testObj)}
			entries = append(entries, &entry{key: b.Key, name: b.Name, elapsed: 0, main: pm, build: b})
		}
	}
	for _, po := range res.panics {
		entries = append(entries, &entry{key: po.Key, name: po.Name, elapsed: po.Elapsed, cover: po.Cover, coverSet: po.CoverSet, cached: po.Cached, panic: po})
	}
	return entries
}

func sortEntries(entries []*entry) {
	sort.Slice(entries, func(i, j int) bool {
		switch optSort {
		case "elapsed":
			return entries[i].elapsed > entries[j].elapsed
		case "cover":
			return entries[i].cover > entries[j].cover
		default:
			return entries[i].name < entries[j].name
		}
	})
}

func cloneSorted(entries []*entry) []*entry {
	out := make([]*entry, len(entries))
	copy(out, entries)
	sortEntries(out)
	return out
}

func render(w io.Writer, res *result) {
	entries := buildEntries(res)
	sorted := cloneSorted(entries)

	showTests := optPass || optSkip || optAll
	showPass := optPass || optAll
	showSkip := optSkip || optAll

	// Test tables
	if showTests {
		if effectiveFormat == "markdown" {
			renderMarkdownTestSections(w, entries)
		} else {
			renderBasicTestTable(w, sorted, showPass, showSkip)
		}
	}

	// Failure / panic sections
	renderFailPanic(w, sorted)

	// Summary
	renderSummary(w, res, entries)
}

func qualifyingRowsForPackage(e *entry, showPass, showSkip bool) [][]string {
	if e.main == nil {
		return nil
	}
	p := e.main
	passTests := []*testObj{}
	skipTests := []*testObj{}
	failTests := []*testObj{}
	for _, t := range p.Tests {
		switch t.status() {
		case "PASS":
			passTests = append(passTests, t)
		case "SKIP":
			skipTests = append(skipTests, t)
		default:
			failTests = append(failTests, t)
		}
	}
	// Sort passes by elapsed descending
	sort.Slice(passTests, func(i, j int) bool {
		return passTests[i].Elapsed > passTests[j].Elapsed
	})
	if optSlow > 0 && len(passTests) > optSlow {
		passTests = passTests[:optSlow]
	}
	var rows [][]string
	mkRow := func(t *testObj) []string {
		return []string{displayStatus(t.status()), fmt.Sprintf("%.2f", t.Elapsed), formatTestName(t.Name), displayPkgName(t.Package)}
	}
	if showPass {
		for _, t := range passTests {
			rows = append(rows, mkRow(t))
		}
	}
	if showSkip {
		for _, t := range skipTests {
			rows = append(rows, mkRow(t))
		}
	}
	for _, t := range failTests {
		rows = append(rows, mkRow(t))
	}
	return rows
}

func renderBasicTestTable(w io.Writer, sorted []*entry, showPass, showSkip bool) {
	var rows [][]string
	for i, e := range sorted {
		if e.isPanic() {
			continue
		}
		if e.main != nil && e.main.NoTest {
			continue
		}
		rows = append(rows, qualifyingRowsForPackage(e, showPass, showSkip)...)
		if i < len(sorted)-1 {
			rows = append(rows, []string{"", "", "", ""})
		}
	}
	if len(rows) == 0 {
		return
	}
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	aligns := []int{alignCenter, alignCenter, alignLeft, alignLeft}
	fmt.Fprint(w, renderTable(headers, rows, aligns, effectiveFormat))
}

func renderMarkdownTestSections(w io.Writer, entries []*entry) {
	// Entries excluding panics and notest main packages, sorted
	var filtered []*entry
	for _, e := range entries {
		if e.isPanic() {
			continue
		}
		if e.main != nil && e.main.NoTest {
			continue
		}
		filtered = append(filtered, e)
	}
	sorted := cloneSorted(filtered)
	showPass := optPass || optAll
	showSkip := optSkip || optAll
	for _, e := range sorted {
		rowsWithPkg := qualifyingRowsForPackage(e, showPass, showSkip)
		if len(rowsWithPkg) == 0 {
			fmt.Fprintln(w, "")
			continue
		}
		// strip package column
		var rows [][]string
		for _, r := range rowsWithPkg {
			rows = append(rows, []string{r[0], r[1], r[2]})
		}
		passC, failC, skipC := 0, 0, 0
		if e.main != nil {
			passC, failC, skipC = e.main.counts()
		}
		pkgHeading := ""
		if e.main != nil {
			pkgHeading = e.main.Name
		} else if e.build != nil {
			pkgHeading = e.build.Name
		}
		headers := []string{"Status", "Elapsed", "Test"}
		aligns := []int{alignCenter, alignCenter, alignLeft}
		tableStr := renderTable(headers, rows, aligns, "markdown")
		section := fmt.Sprintf("## 📦 Package **`%s`**\n\nTests: ✓ %d passed | %d skipped | %d failed\n\n<details>\n\n<summary>Click for test summary</summary>\n\n%s</details>\n\n", pkgHeading, passC, skipC, failC, tableStr)
		fmt.Fprintln(w, section)
	}
}

// ---------- failures / panics ----------

func failedTests(p *pkgObj) []*testObj {
	var out []*testObj
	for _, t := range p.Tests {
		if t.status() == "FAIL" {
			out = append(out, t)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func boxStatusAndName(e *entry) (string, string) {
	if e.panic != nil {
		name := e.panic.Name
		if e.panic.Test != "" {
			// caller handles separately
			_ = name
		}
		return "PANIC", e.panic.Name
	}
	if e.main == nil {
		return "", ""
	}
	st := strings.ToUpper(e.main.Action)
	if st == "" && e.main.NoTest && e.main.NoTestPass {
		st = "PASS"
	}
	return st, e.main.Name
}

func renderFailPanic(w io.Writer, sorted []*entry) {
	for _, e := range sorted {
		if e.isPanic() {
			renderPanic(w, e)
			continue
		}
		if e.main == nil {
			continue
		}
		ft := failedTests(e.main)
		if len(ft) == 0 {
			continue
		}
		if effectiveFormat == "markdown" {
			st, pkgName := boxStatusAndName(e)
			headingStatus := st
			if !noColor {
				headingStatus = "🔴 " + st
			}
			fmt.Fprintf(w, "## %s • %s\n\n", headingStatus, pkgName)
			fmt.Fprint(w, "```\n")
			fmt.Fprint(w, failContent(e.main, true))
			fmt.Fprint(w, "```\n\n")
		} else {
			st, pkgName := boxStatusAndName(e)
			box := makeBox(st, pkgName, false)
			fmt.Fprint(w, box)
			fmt.Fprint(w, "\n")
			fmt.Fprint(w, failContent(e.main, false))
		}
	}
}

func makeBox(status, pkgName string, isPanic bool) string {
	// status display inside box
	var statusDisp string
	if noColor {
		statusDisp = status
	} else {
		statusDisp = "\x1b[91m\x1b[91m" + status + "\x1b[0m\x1b[0m"
	}
	var content string
	// For panic, caller composes content externally; this function is for fail boxes only.
	content = "   " + statusDisp + "  package: " + pkgName + "   "
	visibleContent := "   " + status + "  package: " + pkgName + "   "
	width := displayWidth(visibleContent)
	border := func(s string) string {
		if noColor {
			return s
		}
		return "\x1b[38;5;103m" + s + "\x1b[0m"
	}
	top := border("┏" + strings.Repeat("━", width) + "┓")
	mid := border("┃") + content + border("┃")
	bottom := border("┗" + strings.Repeat("━", width) + "┛")
	return top + "\n" + mid + "\n" + bottom + "\n"
}

func makePanicBox(po *panicObj) (string, string) {
	status := "PANIC"
	var statusDisp string
	if noColor {
		statusDisp = status
	} else {
		statusDisp = "\x1b[91m\x1b[91m" + status + "\x1b[0m\x1b[0m"
	}
	var visible string
	var content string
	if po.Test != "" {
		visible = "   " + status + "  package: " + po.Name + " • " + po.Test + "   "
		content = "   " + statusDisp + "  package: " + po.Name + " • " + po.Test + "   "
	} else {
		visible = "   " + status + "  package: " + po.Name + "   "
		content = "   " + statusDisp + "  package: " + po.Name + "   "
	}
	width := displayWidth(visible)
	border := func(s string) string {
		if noColor {
			return s
		}
		return "\x1b[38;5;103m" + s + "\x1b[0m"
	}
	top := border("┏" + strings.Repeat("━", width) + "┓")
	mid := border("┃") + content + border("┃")
	bottom := border("┗" + strings.Repeat("━", width) + "┛")
	return top + "\n" + mid + "\n" + bottom + "\n", visible
}

func renderPanic(w io.Writer, e *entry) {
	po := e.panic
	if effectiveFormat == "markdown" {
		statusDisp := "PANIC"
		if !noColor {
			statusDisp = "🔴 PANIC"
		}
		heading := "## " + statusDisp + " • " + po.Name
		if po.Test != "" {
			heading += " • " + po.Test
		}
		width := 96
		if dw := displayWidth(heading); dw > width {
			width = dw
		}
		// heading padded
		fmt.Fprint(w, padRight(heading, width)+"\n")
		renderPanicStack(w, po.Stack, width)
	} else {
		box, _ := makePanicBox(po)
		// box lines are already newline terminated; determine width from box visible width
		// visible width = display width of first box line without ANSI
		firstLine := strings.Split(box, "\n")[0]
		width := 96
		if dw := displayWidth(firstLine); dw > width {
			width = dw
		}
		// print box padded
		lines := strings.Split(strings.TrimSuffix(box, "\n"), "\n")
		for _, l := range lines {
			fmt.Fprint(w, padRight(l, width)+"\n")
		}
		renderPanicStack(w, po.Stack, width)
	}
}

func renderPanicStack(w io.Writer, stack string, width int) {
	text := strings.ReplaceAll(stack, "\t", "    ")
	// split into logical lines; strings.Split preserves trailing empty segment
	logical := strings.Split(text, "\n")
	for _, line := range logical {
		wrapped := wrapLineWord(line, width)
		for _, wl := range wrapped {
			fmt.Fprint(w, padRight(wl, width)+"\n")
		}
	}
}

// padRight pads a string (possibly with ANSI) to display width.
func padRight(s string, width int) string {
	dw := displayWidth(s)
	if dw >= width {
		return s
	}
	return s + strings.Repeat(" ", width-dw)
}

// wrapLineWord wraps a single logical line to width using greedy word wrapping,
// breaking long words.
func wrapLineWord(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	if displayWidth(line) <= width {
		return []string{line}
	}
	// Tokenize preserving spaces
	type token struct {
		text  string
		isSpace bool
	}
	var toks []token
	i := 0
	runes := []rune(line)
	for i < len(runes) {
		if runes[i] == ' ' {
			j := i
			for j < len(runes) && runes[j] == ' ' {
				j++
			}
			toks = append(toks, token{string(runes[i:j]), true})
			i = j
		} else {
			j := i
			for j < len(runes) && runes[j] != ' ' {
				j++
			}
			toks = append(toks, token{string(runes[i:j]), false})
			i = j
		}
	}
	var lines []string
	cur := ""
	flush := func() {
		lines = append(lines, cur)
		cur = ""
	}
	for _, tok := range toks {
		if tok.isSpace {
			cur += tok.text
			continue
		}
		// word
		if displayWidth(cur)+displayWidth(tok.text) <= width {
			cur += tok.text
			continue
		}
		// word doesn't fit
		if displayWidth(tok.text) > width {
			// emit current line if any content (even just spaces)
			if cur != "" {
				flush()
			}
			// break word into width sized chunks
			wr := []rune(tok.text)
			// Use display width aware chunking; simple rune slice when ascii
			for displayWidth(string(wr)) > width {
				// take prefix with display width <= width
				end := 0
				wsum := 0
				for end < len(wr) {
					rw := runeDisplayWidth(wr[end])
					if wsum+rw > width {
						break
					}
					wsum += rw
					end++
				}
				if end == 0 {
					end = 1
				}
				lines = append(lines, string(wr[:end]))
				wr = wr[end:]
			}
			cur = string(wr)
			continue
		}
		// fits on its own line
		flush()
		cur = tok.text
	}
	// last line
	lines = append(lines, cur)
	return lines
}

func failContent(p *pkgObj, markdown bool) string {
	ft := failedTests(p)
	var sb strings.Builder
	for i, t := range ft {
		if i > 0 && !strings.Contains(t.Name, "/") {
			sb.WriteString(strings.Repeat("─", 96) + "\n")
			if !markdown && !noColor {
				sb.WriteString("\x1b[2m\x1b[0m")
			}
			sb.WriteString(strings.Repeat(" ", 96) + "\n")
		}
		headers, body := parseTestOutputs(t)
		var headerDisp strings.Builder
		for _, h := range headers {
			if !markdown && !noColor {
				headerDisp.WriteString("\x1b[31m" + h + "\x1b[0m")
			} else {
				headerDisp.WriteString(h)
			}
		}
		sb.WriteString(headerDisp.String() + "\n")
		if body != "" {
			sb.WriteString("\n")
			sb.WriteString(body)
			sb.WriteString("\n")
		}
	}
	return sb.String()
}

func parseTestOutputs(t *testObj) (headers []string, body string) {
	var bodySb strings.Builder
	for _, out := range t.Outputs {
		if idx := strings.Index(out, "--- FAIL: "); idx >= 0 {
			prefix := out[:idx]
			spaces := strings.Count(prefix, " ")
			indent := strings.Repeat(" ", spaces/2)
			seg := out[idx:]
			seg = strings.TrimSuffix(seg, "\n")
			seg = strings.ReplaceAll(seg, "\t", "    ")
			headers = append(headers, indent+seg)
		} else if isTestNoise(out) {
			continue
		} else {
			bodySb.WriteString(out)
		}
	}
	return headers, bodySb.String()
}

// ---------- summary ----------

func renderSummary(w io.Writer, res *result, entries []*entry) {
	// Determine groups
	sorted := cloneSorted(entries)

	var special, regular, notest []*entry
	for _, e := range sorted {
		if e.isPanic() || e.isBuild() {
			// dedupe panic vs build by key: if panic and build both, panic wins later; handle below
			special = append(special, e)
			continue
		}
		if e.main != nil && e.main.NoTest {
			notest = append(notest, e)
			continue
		}
		// cov suppression
		if e.main != nil && len(e.main.Tests) == 0 && e.main.CoverSet && e.main.Cover == 0 {
			continue
		}
		regular = append(regular, e)
	}
	// Dedupe special by key preferring panic
	{
		byKey := make(map[string]*entry)
		var keys []string
		for _, e := range special {
			if existing, ok := byKey[e.key]; ok {
				if existing.isPanic() {
					continue
				}
				if e.isPanic() {
					byKey[e.key] = e
				}
				continue
			}
			byKey[e.key] = e
			keys = append(keys, e.key)
		}
		// rebuild special preserving sorted order but only keep chosen entries
		var deduped []*entry
		seen := make(map[string]bool)
		for _, e := range special {
			chosen := byKey[e.key]
			if chosen == e && !seen[e.key] {
				deduped = append(deduped, e)
				seen[e.key] = true
			}
		}
		special = deduped
		// Remove regular/notest entries whose key is in special
		// (regular already excludes build, panic not in main; but BF duplicate main is in special as main entry, fine)
		_ = keys
	}
	// If a package is in special, it shouldn't also be in notest (already handled: build before notest, panic not main)
	// Inclusion of notest
	showNotest := optNoTests
	if !showNotest {
		if len(res.main) == 1 {
			showNotest = true
		}
	}

	var rows [][]string
	addRow := func(e *entry) {
		st := summaryStatus(e)
		elapsed := ""
		if e.cached {
			elapsed = "(cached)"
		} else {
			elapsed = fmt.Sprintf("%.2fs", e.elapsed)
		}
		cover := "--"
		counts := []string{"--", "--", "--"}
		isSpecialCat := e.isPanic() || e.isBuild() || (e.main != nil && e.main.NoTest)
		if !isSpecialCat && e.coverSet {
			cover = fmt.Sprintf("%.1f%%", e.cover)
		}
		if !isSpecialCat && e.main != nil {
			pc, fc, sc := e.main.counts()
			counts = []string{strconv.Itoa(pc), strconv.Itoa(fc), strconv.Itoa(sc)}
		}
		pkgDisp := ""
		if e.isPanic() {
			pkgDisp = displayPkgName(e.panic.Name)
		} else if e.main != nil {
			base := displayPkgName(e.main.Name)
			if e.isBuild() {
				pkgDisp = base + "\n[" + e.main.BuildMsg + "]"
			} else if e.main.NoTest {
				pkgDisp = base + "\n[" + e.main.NoTestMsg + "]"
			} else {
				pkgDisp = base
			}
		}
		rows = append(rows, []string{displayStatus(st), elapsed, pkgDisp, cover, counts[0], counts[1], counts[2]})
	}
	for _, e := range special {
		addRow(e)
	}
	for _, e := range regular {
		addRow(e)
	}
	if showNotest {
		for _, e := range notest {
			addRow(e)
		}
	}

	if len(rows) == 0 && len(notest) == 0 {
		return
	}
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	aligns := []int{alignCenter, alignCenter, alignLeft, alignCenter, alignCenter, alignCenter, alignCenter}
	fmt.Fprint(w, renderTable(headers, rows, aligns, effectiveFormat))
}

func summaryStatus(e *entry) string {
	if e.isPanic() {
		return "PANIC"
	}
	if e.isBuild() {
		return "FAIL"
	}
	if e.main != nil && e.main.NoTest {
		return "NOTEST"
	}
	if e.main != nil {
		switch e.main.Action {
		case "pass":
			return "PASS"
		case "fail":
			return "FAIL"
		}
	}
	return ""
}

// ---------- table rendering ----------

const (
	alignCenter = iota
	alignLeft
)

func renderTable(headers []string, rows [][]string, aligns []int, style string) string {
	ncols := len(headers)
	// compute widths
	widths := make([]int, ncols)
	for i, h := range headers {
		widths[i] = displayWidth(h)
	}
	// normalize rows and split cells
	type splitRow [][]string
	var splitRows []splitRow
	for _, r := range rows {
		var sr splitRow
		for i := 0; i < ncols; i++ {
			cell := ""
			if i < len(r) {
				cell = r[i]
			}
			// tab expansion to 4 spaces for display (go-pretty like)
			// only if cell does not contain ANSI? keep simple: replace tabs
			// Split into lines
			lines := strings.Split(cell, "\n")
			sr = append(sr, lines)
			for _, ln := range lines {
				if dw := displayWidth(ln); dw > widths[i] {
					widths[i] = dw
				}
			}
		}
		splitRows = append(splitRows, sr)
	}

	var sb strings.Builder
	formatLine := func(cells []string, isHeader bool) string {
		var parts []string
		for i := 0; i < ncols; i++ {
			txt := ""
			if i < len(cells) {
				txt = cells[i]
			}
			aligned := alignText(txt, widths[i], alignCenter) // headers always center
			if !isHeader {
				if aligns[i] == alignLeft {
					aligned = alignText(txt, widths[i], alignLeft)
				} else {
					aligned = alignText(txt, widths[i], alignCenter)
				}
			}
			parts = append(parts, " "+aligned+" ")
		}
		switch style {
		case "markdown":
			return "|" + strings.Join(parts, "|") + "|\n"
		case "plain":
			// replace border with space: build like basic but with spaces
			return " " + strings.Join(parts, " ") + " \n"
		default: // basic
			return "│" + strings.Join(parts, "│") + "│\n"
		}
	}

	if style == "markdown" {
		sb.WriteString(formatLine(headers, true))
		// separator
		var seps []string
		for i := 0; i < ncols; i++ {
			seps = append(seps, strings.Repeat("-", widths[i]+2))
		}
		sb.WriteString("|" + strings.Join(seps, "|") + "|\n")
	} else if style == "plain" {
		sb.WriteString(formatLine(headers, true))
		// blank separator line: total width
		total := 0
		// compute total from a formatted line display width
		hl := formatLine(headers, true)
		total = displayWidth(strings.TrimSuffix(hl, "\n"))
		sb.WriteString(strings.Repeat(" ", total) + "\n")
	} else {
		// basic top
		sb.WriteString(borderLine(widths, "╭", "┬", "╮"))
		sb.WriteString(formatLine(headers, true))
		sb.WriteString(borderLine(widths, "├", "┼", "┤"))
	}
	// rows
	for _, sr := range splitRows {
		maxLines := 1
		for _, cellLines := range sr {
			if len(cellLines) > maxLines {
				maxLines = len(cellLines)
			}
		}
		for li := 0; li < maxLines; li++ {
			var cells []string
			for i := 0; i < ncols; i++ {
				if li < len(sr[i]) {
					cells = append(cells, sr[i][li])
				} else {
					cells = append(cells, "")
				}
			}
			sb.WriteString(formatLine(cells, false))
		}
	}
	if style != "markdown" && style != "plain" {
		sb.WriteString(borderLine(widths, "╰", "┴", "╯"))
	}
	return sb.String()
}

func borderLine(widths []int, left, mid, right string) string {
	var parts []string
	for _, w := range widths {
		parts = append(parts, strings.Repeat("─", w+2))
	}
	return left + strings.Join(parts, mid) + right + "\n"
}

func alignText(s string, width int, align int) string {
	dw := displayWidth(s)
	if dw >= width {
		return s
	}
	pad := width - dw
	if align == alignLeft {
		return s + strings.Repeat(" ", pad)
	}
	left := pad / 2
	right := pad - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

// displayWidth computes visible width stripping ANSI sequences.
var ansiRe = regexp.MustCompile("\x1b\\[[0-9;]*[A-Za-z]")

func displayWidth(s string) int {
	stripped := ansiRe.ReplaceAllString(s, "")
	w := 0
	for _, r := range stripped {
		w += runeDisplayWidth(r)
	}
	return w
}

func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 32 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Cf, r) {
		return 0
	}
	// Wide / fullwidth ranges approximating go-runewidth
	if isWideRune(r) {
		return 2
	}
	return 1
}

func isWideRune(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, // Hangul Jamo
		r >= 0x2329 && r <= 0x232A,
		r >= 0x2E80 && r <= 0x303E,
		r >= 0x3041 && r <= 0x33FF,
		r >= 0x3400 && r <= 0x4DBF,
		r >= 0x4E00 && r <= 0x9FFF,
		r >= 0xA000 && r <= 0xA4C6,
		r >= 0xAC00 && r <= 0xD7A3,
		r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE10 && r <= 0xFE19,
		r >= 0xFE30 && r <= 0xFE52,
		r >= 0xFE54 && r <= 0xFE66,
		r >= 0xFE68 && r <= 0xFE6B,
		r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6,
		r >= 0x16FE0 && r <= 0x16FE4,
		r >= 0x17000 && r <= 0x187F7,
		r >= 0x18800 && r <= 0x18CD5,
		r >= 0x1B000 && r <= 0x1B2FB,
		r >= 0x1F004 && r <= 0x1F004,
		r >= 0x1F0CF && r <= 0x1F0CF,
		r >= 0x1F18E && r <= 0x1F18E,
		r >= 0x1F191 && r <= 0x1F19A,
		r >= 0x1F200 && r <= 0x1F320,
		r >= 0x1F32D && r <= 0x1F335,
		r >= 0x1F337 && r <= 0x1F37C,
		r >= 0x1F37E && r <= 0x1F393,
		r >= 0x1F3A0 && r <= 0x1F3CA,
		r >= 0x1F3CF && r <= 0x1F3D3,
		r >= 0x1F3E0 && r <= 0x1F3F0,
		r >= 0x1F3F4 && r <= 0x1F3F4,
		r >= 0x1F3F8 && r <= 0x1F43E,
		r >= 0x1F440 && r <= 0x1F440,
		r >= 0x1F442 && r <= 0x1F4FC,
		r >= 0x1F4FF && r <= 0x1F53D,
		r >= 0x1F54B && r <= 0x1F54E,
		r >= 0x1F550 && r <= 0x1F567,
		r >= 0x1F57A && r <= 0x1F57A,
		r >= 0x1F595 && r <= 0x1F596,
		r >= 0x1F5A4 && r <= 0x1F5A4,
		r >= 0x1F5FB && r <= 0x1F64F,
		r >= 0x1F680 && r <= 0x1F6C5,
		r >= 0x1F6CC && r <= 0x1F6CC,
		r >= 0x1F6D0 && r <= 0x1F6D2,
		r >= 0x1F6D5 && r <= 0x1F6D7,
		r >= 0x1F6DC && r <= 0x1F6DF,
		r >= 0x1F6EB && r <= 0x1F6EC,
		r >= 0x1F6F4 && r <= 0x1F6FC,
		r >= 0x1F7E0 && r <= 0x1F7EB,
		r >= 0x1F7F0 && r <= 0x1F7F0,
		r >= 0x1F90C && r <= 0x1F93A,
		r >= 0x1F93C && r <= 0x1F945,
		r >= 0x1F947 && r <= 0x1F9CB,
		r >= 0x1F9CD && r <= 0x1F9FF,
		r >= 0x1FA70 && r <= 0x1FA74,
		r >= 0x1FA78 && r <= 0x1FA7C,
		r >= 0x1FA80 && r <= 0x1FA86,
		r >= 0x1FA90 && r <= 0x1FAAC,
		r >= 0x1FAB0 && r <= 0x1FABA,
		r >= 0x1FAC0 && r <= 0x1FAC5,
		r >= 0x1FAD0 && r <= 0x1FAD9,
		r >= 0x1FAE0 && r <= 0x1FAE7,
		r >= 0x1FAF0 && r <= 0x1FAF6,
		r >= 0x20000 && r <= 0x2FFFD,
		r >= 0x30000 && r <= 0x3FFFD:
		return true
	}
	return false
}
