	flag.StringVar(&optFormat, "format", "basic", "")
	flag.StringVar(&optFile, "file", "", "")
	flag.BoolVar(&optFollow, "follow", false, "")
	flag.StringVar(&optFollowOutput, "follow-output", "", "")
	flag.BoolVar(&optIncludeTimestamp, "include-timestamp", false, "")
	flag.BoolVar(&optProgress, "progress", false, "")
	flag.StringVar(&optCompare, "compare", "", "")
