import pathlib
p=pathlib.Path("main.go")
t=p.read_text()
start=t.index('// wrapLineWord wraps')
end=t.index('func failContent')
new=r'''// wrapLineWord wraps a single logical line to width using greedy word wrapping,
// breaking long words.
func wrapLineWord(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	if displayWidth(line) <= width {
		return []string{line}
	}
	type token struct {
		text    string
		isSpace bool
	}
	var toks []token
	runes := []rune(line)
	for i := 0; i < len(runes); {
		if runes[i] == ' ' {
			j := i
			for j < len(runes) && runes[j] == ' ' {
				j++
			}
			toks = append(toks, token{string(runes[i:j]), true})
			i = j
		} else {
			j := i
			for j < len(runes) && runes[j] != ' ' {
				j++
			}
			toks = append(toks, token{string(runes[i:j]), false})
			i = j
		}
	}
	var lines []string
	cur := ""
	pendingSpace := ""
	flush := func() {
		lines = append(lines, cur)
		cur = ""
	}
	for _, tok := range toks {
		if tok.isSpace {
			pendingSpace += tok.text
			continue
