new='''func displayPkgName(name string) string {
	if optTrimPath != "" {
		name = strings.TrimPrefix(name, optTrimPath)
	}
	if optSmallScreen {
		if smallCommonDirSegs == 0 {
			if idx := strings.LastIndex(name, "/"); idx >= 0 {
				name = name[idx+1:]
			}
		} else {
			segs := strings.Split(name, "/")
			if len(segs) <= smallCommonDirSegs {
				return ""
			}
			name = strings.Join(segs[smallCommonDirSegs:], "/")
		}
	}
	return name
}

func computeSmallCommon(entries []*entry) {
	smallCommonDirSegs = 0
	if !optSmallScreen || len(entries) == 0 {
		return
	}
	var dirSegs [][]string
	for _, e := range entries {
		src := ""
		if e.panic != nil {
			src = e.panic.Name
		} else if e.main != nil {
			src = e.main.Name
		} else if e.build != nil {
			src = e.build.Name
		}
		if optTrimPath != "" {
			src = strings.TrimPrefix(src, optTrimPath)
		}
		segs := strings.Split(src, "/")
		var dir []string
		if len(segs) > 1 {
			dir = segs[:len(segs)-1]
		}
		dirSegs = append(dirSegs, dir)
	}
	// longest common segment prefix among all dir lists
	for i := 0; ; i++ {
		var cur string
		ok := true
		for j, ds := range dirSegs {
			if i >= len(ds) {
				ok = false
				break
			}
			if j == 0 {
				cur = ds[i]
			} else if ds[i] != cur {
				ok = false
				break
			}
		}
		if !ok {
			break
		}
		smallCommonDirSegs++
	}
}'''
